  @protected
  void sse_encode_app_event(AppEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case AppEvent_MessageReceived(
        conversationId: final conversationId,
        fromName: final fromName,
        fromFingerprint: final fromFingerprint,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_String(conversationId, serializer);
        sse_encode_String(fromName, serializer);
        sse_encode_String(fromFingerprint, serializer);
      case AppEvent_ContactRequested(
        requestId: final requestId,
        name: final name,
        fingerprint: final fingerprint,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_u_64(requestId, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(fingerprint, serializer);
      case AppEvent_ContactAdded(
        name: final name,
        fingerprint: final fingerprint,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(fingerprint, serializer);
      case AppEvent_RoleChanged(from: final from, to: final to):
        sse_encode_i_32(3, serializer);
        sse_encode_String(from, serializer);
        sse_encode_String(to, serializer);
      case AppEvent_Transfer(
        name: final name,
        done: final done,
        total: final total,
        upload: final upload,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(name, serializer);
        sse_encode_u_64(done, serializer);
        sse_encode_u_64(total, serializer);
        sse_encode_bool(upload, serializer);
      case AppEvent_GroupJoined(
        groupId: final groupId,
        name: final name,
        creator: final creator,
        exposed: final exposed,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_String(groupId, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(creator, serializer);
        sse_encode_list_String(exposed, serializer);
      case AppEvent_GroupUpdated(groupId: final groupId, name: final name):
        sse_encode_i_32(6, serializer);
        sse_encode_String(groupId, serializer);
        sse_encode_String(name, serializer);
      case AppEvent_GroupRemoved(groupId: final groupId, name: final name):
        sse_encode_i_32(7, serializer);
        sse_encode_String(groupId, serializer);
        sse_encode_String(name, serializer);
      case AppEvent_CallSignal(
        fromFingerprint: final fromFingerprint,
        fromName: final fromName,
        payload: final payload,
      ):
        sse_encode_i_32(8, serializer);
        sse_encode_String(fromFingerprint, serializer);
        sse_encode_String(fromName, serializer);
        sse_encode_String(payload, serializer);
      case AppEvent_Lagged():
        sse_encode_i_32(9, serializer);
    }
  }

